import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DaGSOal_.js";const u=JSON.parse('{"title":"Features","description":"","frontmatter":{"sidebar_position":3},"headers":[],"relativePath":"loading-screen-pro/features.md","filePath":"loading-screen-pro/features.md","lastUpdated":1776967206000}'),n={name:"loading-screen-pro/features.md"};function i(s,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><h2 id="visual-styles" tabindex="-1">Visual Styles <a class="header-anchor" href="#visual-styles" aria-label="Permalink to &quot;Visual Styles&quot;">​</a></h2><h3 id="progress-bar" tabindex="-1">Progress Bar <a class="header-anchor" href="#progress-bar" aria-label="Permalink to &quot;Progress Bar&quot;">​</a></h3><p>Choose from three styles in the <strong>Progress Bar</strong> category of your Data Asset:</p><ul><li><strong>Bar</strong> — classic solid or gradient-filled bar with a subtle leading-edge highlight</li><li><strong>Segmented</strong> — smooth fill divided by thin vertical dividers for a chunky, game-style look</li><li><strong>Stepped</strong> — 20 discrete cells that switch fully on or off as progress advances</li></ul><p>All styles support gradient fill and an optional percentage label.</p><h3 id="spinner" tabindex="-1">Spinner <a class="header-anchor" href="#spinner" aria-label="Permalink to &quot;Spinner&quot;">​</a></h3><p>Choose from four styles in the <strong>Spinner</strong> category:</p><ul><li><strong>Ring</strong> — rotating dot ring with a trailing opacity fade (default)</li><li><strong>Arc</strong> — 270° arc sweep where the head is bright and the tail fades out</li><li><strong>Bars</strong> — 8 radial bar segments that rotate (classic macOS-style)</li><li><strong>Dots</strong> — three horizontally arranged dots that bounce in a wave pattern</li></ul><p>Assign a <strong>Custom Spinner Texture</strong> to replace any built-in style with your own PNG.</p><h3 id="ken-burns-effect" tabindex="-1">Ken Burns Effect <a class="header-anchor" href="#ken-burns-effect" aria-label="Permalink to &quot;Ken Burns Effect&quot;">​</a></h3><p>Slowly zooms each image over its display duration — adds cinematic depth to any slide.<br> Adjustable intensity (0–30%). Recommended: 4–12%.</p><h3 id="cinematic-overlays" tabindex="-1">Cinematic Overlays <a class="header-anchor" href="#cinematic-overlays" aria-label="Permalink to &quot;Cinematic Overlays&quot;">​</a></h3><ul><li><strong>Vignette</strong> — soft dark gradient around the screen edges</li><li><strong>Letterbox</strong> — black bars at top and bottom for a widescreen look</li><li><strong>Screen fade-in</strong> — automatic fade from black when the loading screen first appears</li></ul><h2 id="media-sequence" tabindex="-1">Media Sequence <a class="header-anchor" href="#media-sequence" aria-label="Permalink to &quot;Media Sequence&quot;">​</a></h2><p>Add images to the <strong>Media Sequence</strong> array to create a slideshow. Each entry supports:</p><ul><li>Individual <strong>display duration</strong></li><li>Individual <strong>transition effect</strong> (Fade, Slide Left, Slide Right, Fade to Black, Zoom In, Cut)</li><li>Individual <strong>transition duration</strong></li><li><strong>Per-slide hint override</strong> — show a specific hint for a specific image</li><li><strong>Per-slide transition sound</strong> — play a sound when this slide transitions</li></ul><p>Leave the Media Sequence empty for a plain spinner screen with background color.</p><h2 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h2><ul><li><strong>Background Music</strong> — plays during loading, fades out automatically after the level loads</li><li><strong>Fade-in duration</strong> — configurable ramp-up time (0 = instant full volume)</li><li><strong>Transition Sound</strong> — global sound played on every slide change (overridable per slide)</li><li>Music also plays in the <strong>editor preview window</strong></li></ul><h2 id="hud-elements" tabindex="-1">HUD Elements <a class="header-anchor" href="#hud-elements" aria-label="Permalink to &quot;HUD Elements&quot;">​</a></h2><h3 id="hints-tips" tabindex="-1">Hints / Tips <a class="header-anchor" href="#hints-tips" aria-label="Permalink to &quot;Hints / Tips&quot;">​</a></h3><p>Add any number of hints to the <strong>Hints</strong> array. Each hint supports an optional icon texture.<br> Display mode: <strong>Random</strong> or <strong>Sequential</strong>. Hints fade in and out smoothly.</p><h3 id="logo" tabindex="-1">Logo <a class="header-anchor" href="#logo" aria-label="Permalink to &quot;Logo&quot;">​</a></h3><p>Display a studio or game logo in any corner. Configurable size, opacity, and position.</p><h3 id="overlay-text" tabindex="-1">Overlay Text <a class="header-anchor" href="#overlay-text" aria-label="Permalink to &quot;Overlay Text&quot;">​</a></h3><p>Show a line of custom text (game title, level name, etc.) at any anchor point on screen.</p><h3 id="sequence-dots" tabindex="-1">Sequence Dots <a class="header-anchor" href="#sequence-dots" aria-label="Permalink to &quot;Sequence Dots&quot;">​</a></h3><p>Small animated dots at the bottom showing the active slide. Toggle via <code>Show Sequence Dots</code>.</p><h2 id="workflow-tools" tabindex="-1">Workflow Tools <a class="header-anchor" href="#workflow-tools" aria-label="Permalink to &quot;Workflow Tools&quot;">​</a></h2><h3 id="quick-setup" tabindex="-1">Quick Setup <a class="header-anchor" href="#quick-setup" aria-label="Permalink to &quot;Quick Setup&quot;">​</a></h3><p><strong>Project Settings → Loading Screen Pro</strong> contains a green <strong>✚ Create &amp; Assign Default Loading Screen Asset</strong> button.<br> One click creates <code>Content/LoadingScreenPro/DA_DefaultLoadingScreen</code>, assigns it as the default, and opens it for editing.</p><h3 id="in-editor-preview" tabindex="-1">In-Editor Preview <a class="header-anchor" href="#in-editor-preview" aria-label="Permalink to &quot;In-Editor Preview&quot;">​</a></h3><p>Every Data Asset has a <strong>▶ Preview Loading Screen</strong> button at the top.<br> Opens a live 1280×720 window showing the exact loading screen — including animations, transitions, and music.</p><h3 id="color-presets" tabindex="-1">Color Presets <a class="header-anchor" href="#color-presets" aria-label="Permalink to &quot;Color Presets&quot;">​</a></h3><p>Select a preset from the <strong>Color Preset</strong> dropdown to apply a complete color theme in one click:</p><ul><li><strong>Dark</strong> — dark background, blue progress bar</li><li><strong>Minimal</strong> — light background, dark UI</li><li><strong>Cinematic</strong> — black background, gold gradient bar, vignette, letterbox</li><li><strong>Bright</strong> — blue background, white bar</li></ul><p>The preset resets to <strong>None</strong> after applying so you can keep tweaking from there.</p><h2 id="blueprint-api" tabindex="-1">Blueprint API <a class="header-anchor" href="#blueprint-api" aria-label="Permalink to &quot;Blueprint API&quot;">​</a></h2><p>All nodes are available in Blueprints under the <strong>Loading Screen Pro</strong> category.</p><table tabindex="0"><thead><tr><th>Node</th><th>Description</th></tr></thead><tbody><tr><td><code>Show Loading Screen</code></td><td>Display a loading screen (pass None for default)</td></tr><tr><td><code>Hide Loading Screen</code></td><td>Dismiss the loading screen</td></tr><tr><td><code>Is Loading Screen Active</code></td><td>Check if a loading screen is currently visible</td></tr><tr><td><code>Set Loading Progress</code></td><td>Push a custom progress value (0.0–1.0) from Blueprint</td></tr><tr><td><code>Clear Loading Progress Override</code></td><td>Revert to automatic progress</td></tr><tr><td><code>Get Loading Progress</code></td><td>Read current progress value</td></tr></tbody></table><h3 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>Description</th></tr></thead><tbody><tr><td><code>On Loading Screen Shown</code></td><td>Fires when a loading screen becomes visible</td></tr><tr><td><code>On Loading Screen Hidden</code></td><td>Fires when the loading screen is dismissed</td></tr><tr><td><code>On Slide Changed</code></td><td>Fires with the new slide index on every slide change</td></tr></tbody></table>',43)])])}const p=t(n,[["render",i]]);export{u as __pageData,p as default};
